package com.skyrpg.combat.client.mob;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * The Sporeling's cubes and their UVs. GENERATED by tools/art/generate_sporeling.py from the same cube table
 * the textures are painted from: edit the table there, never this file.
 */
final class SporelingLayout {
    private SporelingLayout() {
    }

    static LayerDefinition create() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        PartDefinition p_body = root.addOrReplaceChild("body",
        CubeListBuilder.create()
                .texOffs(40, 15).addBox(-3f, -5f, -2.5f, 6f, 5f, 5f)
                , PartPose.offset(0f, 21f, 0f));
        p_body.addOrReplaceChild("cap",
        CubeListBuilder.create()
                .texOffs(0, 15).addBox(-5f, -1f, -5f, 10f, 1f, 10f)
                .texOffs(0, 0).addBox(-6f, -4f, -6f, 12f, 3f, 12f)
                .texOffs(24, 26).addBox(-5f, -6f, -5f, 10f, 2f, 10f)
                .texOffs(0, 26).addBox(-3f, -7f, -3f, 6f, 1f, 6f)
                , PartPose.offset(0f, -5f, 0f));
        p_body.addOrReplaceChild("arm_r",
        CubeListBuilder.create()
                .texOffs(0, 38).addBox(-1.5f, -0.5f, -1f, 2f, 4f, 2f)
                , PartPose.offsetAndRotation(-3f, -3.5f, 0f, 0f, 0f, 0.22f));
        p_body.addOrReplaceChild("arm_l",
        CubeListBuilder.create()
                .mirror(true)
                .texOffs(0, 38).addBox(-0.5f, -0.5f, -1f, 2f, 4f, 2f)
                , PartPose.offsetAndRotation(3f, -3.5f, 0f, 0f, 0f, -0.22f));
        root.addOrReplaceChild("leg_r",
        CubeListBuilder.create()
                .texOffs(8, 38).addBox(-1.5f, 0f, -1.5f, 3f, 3f, 3f)
                .texOffs(20, 38).addBox(-1.5f, 2f, -2.5f, 3f, 1f, 1f)
                , PartPose.offset(-1.6f, 21f, 0f));
        root.addOrReplaceChild("leg_l",
        CubeListBuilder.create()
                .mirror(true)
                .texOffs(8, 38).addBox(-1.5f, 0f, -1.5f, 3f, 3f, 3f)
                .texOffs(20, 38).addBox(-1.5f, 2f, -2.5f, 3f, 1f, 1f)
                , PartPose.offset(1.6f, 21f, 0f));
        return LayerDefinition.create(mesh, 64, 64);
    }
}
